const LENS_ZOOM = 3.4;

type LensStop = {
  /** Lens top-left as fractions of the portrait box */
  x: number;
  y: number;
  label: string;
  /** Unique local drift while dwelling on this region */
  motion: "orbit" | "figure8" | "sweep" | "bob" | "zigzag";
};

const LENS_STOPS: LensStop[] = [
  // Lens top-left so the glass center sits on each woman3 feature
  { x: 0.42, y: 0.28, label: "Skin clarity", motion: "orbit" },
  { x: 0.46, y: 0.14, label: "Forehead tone", motion: "sweep" },
  { x: 0.44, y: 0.72, label: "Dress style", motion: "figure8" },
  { x: 0.22, y: 0.32, label: "Hair shape", motion: "zigzag" },
  { x: 0.48, y: 0.4, label: "Lip definition", motion: "bob" },
];

/** Visible dwell — includes local pan time around each region */
const DWELL_MS = 7000;
const FADE_MS = 1200;
const ENTER_DELAY_MS = 900;
const PAN_RADIUS_X = 0.045;
const PAN_RADIUS_Y = 0.038;
const PAN_PERIOD_MS = 4500;

function offsetForMotion(
  motion: LensStop["motion"],
  t: number,
): { dx: number; dy: number } {
  const angle = t * Math.PI * 2;
  switch (motion) {
    case "orbit":
      // Soft clockwise ellipse
      return {
        dx: Math.cos(angle) * PAN_RADIUS_X,
        dy: Math.sin(angle) * PAN_RADIUS_Y,
      };
    case "sweep":
      // Slow horizontal arc with a gentle lift
      return {
        dx: Math.sin(angle) * PAN_RADIUS_X * 1.35,
        dy: Math.sin(angle * 2) * PAN_RADIUS_Y * 0.45,
      };
    case "figure8":
      // Lemniscate — crosses through the center
      return {
        dx: Math.sin(angle) * PAN_RADIUS_X * 1.15,
        dy: Math.sin(angle * 2) * PAN_RADIUS_Y * 0.85,
      };
    case "bob":
      // Mostly vertical pulse with a slight sway
      return {
        dx: Math.sin(angle * 0.5) * PAN_RADIUS_X * 0.4,
        dy: Math.sin(angle) * PAN_RADIUS_Y * 1.25,
      };
    case "zigzag":
      // Diagonal back-and-forth
      return {
        dx: Math.sin(angle) * PAN_RADIUS_X * 1.1,
        dy: Math.cos(angle * 2) * PAN_RADIUS_Y * 0.9,
      };
  }
}

function SkinGlassLens({
  active,
  imageSrc,
}: {
  active: boolean;
  imageSrc: string;
}) {
  const lensRef = useRef<HTMLDivElement>(null);
  const zoomRef = useRef<HTMLImageElement>(null);
  const [ready, setReady] = useState(false);
  const [label, setLabel] = useState(LENS_STOPS[0].label);
  const [visible, setVisible] = useState(false);

  useEffect(() => {
    if (!active) return;
    const id = window.setTimeout(() => setReady(true), 80);
    return () => window.clearTimeout(id);
  }, [active]);

  useEffect(() => {
    if (!ready) return;

    const lens = lensRef.current;
    const zoom = zoomRef.current;
    const parent = lens?.parentElement;
    if (!lens || !zoom || !parent) return;

    const reduced = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
    let cancelled = false;
    let fadeTimer = 0;
    let dwellTimer = 0;
    let raf = 0;
    let stopIndex = 0;

    const placeAt = (xFrac: number, yFrac: number) => {
      const pw = parent.clientWidth;
      const ph = parent.clientHeight;
      const size = lens.offsetWidth;
      const left = xFrac * pw;
      const top = yFrac * ph;
      const cx = left + size / 2;
      const cy = top + size / 2;

      lens.style.left = `${left}px`;
      lens.style.top = `${top}px`;

      zoom.style.width = `${pw * LENS_ZOOM}px`;
      zoom.style.height = `${ph * LENS_ZOOM}px`;
      zoom.style.left = `${size / 2 - cx * LENS_ZOOM}px`;
      zoom.style.top = `${size / 2 - cy * LENS_ZOOM}px`;
    };

    const stopPan = () => {
      if (raf) {
        window.cancelAnimationFrame(raf);
        raf = 0;
      }
    };

    const startPan = (stop: LensStop) => {
      stopPan();
      if (reduced) {
        placeAt(stop.x, stop.y);
        return;
      }

      const origin = performance.now();
      const tick = (now: number) => {
        if (cancelled) return;
        const t = ((now - origin) % PAN_PERIOD_MS) / PAN_PERIOD_MS;
        const { dx, dy } = offsetForMotion(stop.motion, t);
        placeAt(stop.x + dx, stop.y + dy);
        raf = window.requestAnimationFrame(tick);
      };
      raf = window.requestAnimationFrame(tick);
    };

    const showStop = (index: number) => {
      if (cancelled) return;
      const stop = LENS_STOPS[index];
      placeAt(stop.x, stop.y);
      setLabel(stop.label);
      setVisible(true);
      startPan(stop);

      if (reduced) return;

      dwellTimer = window.setTimeout(() => {
        if (cancelled) return;
        stopPan();
        placeAt(stop.x, stop.y);
        setVisible(false);
        fadeTimer = window.setTimeout(() => {
          if (cancelled) return;
          stopIndex = (index + 1) % LENS_STOPS.length;
          showStop(stopIndex);
        }, FADE_MS);
      }, DWELL_MS);
    };

    placeAt(LENS_STOPS[0].x, LENS_STOPS[0].y);
    setLabel(LENS_STOPS[0].label);
    fadeTimer = window.setTimeout(() => showStop(0), ENTER_DELAY_MS);

    const onResize = () => {
      const stop = LENS_STOPS[stopIndex];
      placeAt(stop.x, stop.y);
    };
    window.addEventListener("resize", onResize);

    return () => {
      cancelled = true;
      stopPan();
      window.clearTimeout(fadeTimer);
      window.clearTimeout(dwellTimer);
      window.removeEventListener("resize", onResize);
    };
  }, [ready]);

  return (
    <div
      ref={lensRef}
      className={`skin-glass-lens pointer-events-none absolute z-20 ${
        active && visible ? "is-active" : ""
      }`}
      aria-hidden
    >
      <div className="skin-glass-lens__ring">
        <div className="skin-glass-lens__zoom">
          {/* eslint-disable-next-line @next/next/no-img-element */}
          <img
            ref={zoomRef}
            src={imageSrc}
            alt=""
            className="skin-glass-lens__zoom-img"
            draggable={false}
          />
        </div>
        <span className="skin-glass-lens__glare" />
      </div>
      <span className="skin-glass-lens__label">{label}</span>
    </div>
  );
}

